// The mItems element constructors produce retail's array-initialization
// loop ahead of the counter stores and the memset.
CfMapItemManager::CfMapItemManager() : mCount(0), field_3806(0) {
    memset(mItems, 0, sizeof(mItems));
}

CfMapItemManager::~CfMapItemManager() {}

// Clear every loaded map item (releasing each through the hikari-item
// manager singleton), then reset the manager's bookkeeping and item array.
void CfMapItemManager::clearMapItems() {
    CfMapItemManager* self = this;
    u32 zero = 0;
    for (u32 i = 1; i < self->mCount; i++) {
        u32* handle = &self->mItems[i].handle;
        u32 h = *handle;
        if (h != 0) {
            hikariRemoveRecordTarget(ClearMenu_GetGlobal10(), reinterpret_cast<CfHikariItemRecord*>(h));
            *handle = zero;
        }
    }
    self->mCount = 0;
    self->field_3806 = 0;
    memset(self->mItems, 0, 0x3800);
}

// Column-name scratch keys and sdata2 constants used by placeMapItemPick.
// (sMapItemIdScratchKey is defined at the top of this TU.)

#pragma push
#pragma auto_inline off
int CfMapItemManager::placeMapItemPick(u32 row, void* c, int pick) {
    CfMapItemManager* self = this;
    MapItemBuffer* buf = static_cast<MapItemBuffer*>(c);

    void* table = (void*)self->getItemTable();
    // Build the "itm<pick>Per" weight-column key for this lottery slot.
    char* key = (char*)sMapItemIdScratchKey;
    key[3] = '1' + pick;

    // Spawn-offset columns (x/y/z) arrive as signed shorts converted to float.
    ml::CVec3 offs;
    BdatCell cellX;
    cellX.raw = getBdatStringColumnValue(table, "posX", row);
    offs.x = cellX.s;

    BdatCell cellY;
    cellY.raw = getBdatStringColumnValue(table, "posY", row);
    offs.y = cellY.s;

    BdatCell cellZ;
    cellZ.raw = getBdatStringColumnValue(table, "posZ", row);
    offs.z = cellZ.s;

    BdatCell cellCount;
    cellCount.raw = getBdatStringColumnValue(table, "Radius", row);
    u32 count = cellCount.u;

    BdatCell cellFlag;
    cellFlag.raw = getBdatStringColumnValue(table, "snap", row);
    u8 flag = cellFlag.b;

    BdatCell cellSel;
    cellSel.raw = getBdatStringColumnValue(table, key, row);
    u32 sel = cellSel.u;

    // Clear the previous lottery-slot field, insert the new pick, and drop the
    // "position resolved" bit.
    u32 flags = buf->field_18;
    flags = (flags & ~0x7000u) | ((pick << 17) & 0x7000u);
    flags &= ~0x40000u;
    buf->field_18 = flags;

    if (sel == 0) {
        // No weight for this pick: fall back to the plain itm1Per column.
        sMapItemIdScratchKey[3] = '1';
        cellSel.raw = getBdatStringColumnValue(table, key, row);
        sel = cellSel.u;
        if (sel != 0) {
            buf->field_18 &= ~0x7000u;
        }
    }

    if (sel != 0) {
        // Try up to 16 randomized offsets around the spawn point until a
        // ground probe succeeds.
        int placed = 0;
        ml::CVec3 rnd;      // raw random offset
        ml::CVec3 scaled;   // random offset scaled by the spread factor
        ml::CVec3 center;   // column offsets as a vector
        ml::CVec3 pos;      // candidate position
        ml::CVec3 cur;      // accepted position
        ml::CVec3 probe;    // probe segment endpoint
        for (int i = 0; i < 16; i++) {
            VecMath_RandomAngleOffset(&rnd, count * 100);
            scaled = rnd * 0.01f;
            center.set(scaled);
            pos = center + offs;
            cur = pos;
            probe = pos;
            if (flag == 0) {
                // No facing flag: accept whatever offset was drawn.
                placed = 1;
                continue;
            }
            float ang;
            if (self->isEventActive()) {
                ang = 0.0f;
            } else {
                f32 angleScale = 45.0f;
                ang = nw4r::math::SinFIdx(ml::deg2rad * angleScale * 40.743664f);
            }
            probe.y -= 1.0f;
            if (VecMath_GroundProbeDown(&probe, &cur, 0x4a05, 30.0f, ang)) {
                placed = 1;
                break;
            }
            // Shrink the random-offset table window between attempts.
            count = ((count << 4) - count) >> 4;
        }

        // Snap to the ground height when the object supports it.
        if (self->isEventActive() && placed == 0) {
            placed = 1;
            cur = offs;
            buf->field_18 |= 0x2000;
        }

        if (placed != 0) {
            // Commit the resolved position: y is lifted by the ground offset,
            // x/z are transferred as raw bit patterns.
            cur.y += 0.5f;
            buf->field_08 = *(u32*)&cur.y;

            buf->field_04 = *(u32*)&cur.x;
            buf->field_0C = *(u32*)&cur.z;
            buf->field_14 = (u16)sel;
            buf->field_00 = 0;
            buf->field_18 =
                (buf->field_18 | ((row >> 12) & 0xFFFu)) & ~0x38000u;
            buf->field_10 = 0.0f;
            buf->field_16 = 0;
        } else {
            self->isEventActive();
            sel = 0;
        }
    }

    return (u16)sel;
}
#pragma pop

// cf::CfMapItemManager +0x0C slot: no event active.
int CfMapItemManager::isEventActive() { return 0; }

// sdata scratch key: "itm?Per" - byte 3 is rewritten each iteration with
// '1'+i to select lottery weight column itm1Per..itm8Per.
// (sMapItemPerScratchKey is defined at the top of this TU.)

// Weighted lottery over up to 8 columns: roll mtRand(100), walk cumulative
// weights from the bdat row, and forward the winning column index.
#pragma push
#pragma auto_inline off
// cf::CfMapItemManager +0x10 slot: weighted lottery over itm1Per..itm8Per,
// then place via placeMapItemPick with the winning column.
int CfMapItemManager::placeItem(u32 row, void* item) {
    // Declaration order controls callee-saved register assignment; this
    // ordering reproduces retail's r26-r31 allocation.
    int pick;
    int rnd;
    void* table;
    int i;
    int total;
    // Column values are consumed as their low byte; keeping the raw return
    // in a union reproduces retail's stw-then-lbz memory temp.
    union {
        u32 raw;
        u8 b;
    } col;

    total = 0;
    rnd = ml::math::mtRand(100);
    pick = 0;
    table = (void*)getItemTable();
    for (i = 0; i < 8; i++) {
        sMapItemPerScratchKey[3] = '1' + i;
        col.raw = getBdatStringColumnValue(table, (const char*)sMapItemPerScratchKey, row);
        int next = col.b + total;
        if (rnd >= total && rnd < next) {
            pick = i;
            break;
        }
        total = next;
    }
    return placeMapItemPick(row, item, pick);
}
#pragma pop

// cf::CfValueItemManager +0x10 override: place with lottery pick 0.
int CfValueItemManager::placeItem(u32 row, void* item) {
    return placeMapItemPick(row, item, 0);
}

